import React, { useRef } from 'react';
import emailjs from '@emailjs/browser';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import './Contact.css';

function Contact() {

  this.state = {
    name: '',
    email: '',
    message: '',
  };

  const handleEmailChange = (evt) => {
    this.setState({ email: evt.target.value });
  }

  handleNameChange = (evt) => {
    this.setState({ name: evt.target.value });
  }

  handleMessageChange = (evt) => {
    this.setState({ message: evt.target.value });
  }

  const form = useRef();

  const sendEmail = (e) => {
    e.preventDefault();

    emailjs
      .sendForm('service_gt0vhwi', 'template_41osrfo', form.current, {
        publicKey: '14Elam1xP57BudDQF',
      })
      .then(
        () => {
          toast('Message Sent!');
          console.log('SUCCESS!');
          form.current.reset();
        },
        (error) => {
          toast('Oops! There was an error!');
          console.log('FAILED...', error.text);
        },
      );
  };

  const { email, name, message } = this.state;
  const enabled =
    email.length > 0 &&
    name.length > 0 && message.length > 0;

  return (
    <div className="Contact">
      <h1>Contact</h1>
      <h3>Please feel free to reach out for any inquiries</h3>
      <ToastContainer position='top-center' />
      <form ref={form} onSubmit={sendEmail}>
        <label>Name<span>*</span></label>
        <input type="text" name="user_name" value={this.state.name} onChange={this.handleNameChange} />
        <label>Email Address<span>*</span></label>
        <input type="email" name="user_contact" value={this.state.email} onChange={this.handleEmailChange} />
        <label>Location</label>
        <input type="text" name="user_location" />
        <label>Message<span>*</span></label>
        <textarea name="message" value={this.state.message} onChange={this.handleMessageChange} />
        <input type="submit" value="Send" />
      </form>
    </div>
  );
}

export default Contact;
